const TUNER_STORAGE_KEY='marvel-champions-encounter-tuner-v1';
function readTunerSettings(){try{const saved=JSON.parse(localStorage.getItem(TUNER_STORAGE_KEY)||'{}');return{playerCount:['solo','two','group'].includes(saved.playerCount)?saved.playerCount:'two',moduleChoices:saved.moduleChoices&&typeof saved.moduleChoices==='object'?saved.moduleChoices:{}}}catch{return{playerCount:'two',moduleChoices:{}}}}
const savedTunerSettings=readTunerSettings();
const state={query:'',campaign:'all',hideRepeats:false,expanded:true,playerCount:savedTunerSettings.playerCount,moduleChoices:savedTunerSettings.moduleChoices};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const norm=s=>(s||'').toLowerCase().normalize('NFKD').replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const ratingKey=s=>(s||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,' ').trim();
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
function persistTunerSettings(){try{localStorage.setItem(TUNER_STORAGE_KEY,JSON.stringify({playerCount:state.playerCount,moduleChoices:state.moduleChoices}))}catch{}}
const initials=name=>name.replace(/\([^)]*\)/g,'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function characterCard(id,repeat=false){const m=DATA.characters[id]||{display:id,role:'hero',aliases:[id],hints:[]},url=`images/portraits/${id}.webp`,deckRec=MARVELCDB_DECKS[id],deck=m.role==='hero'?(deckRec?`<a class="deck-link" href="${deckRec.url}" target="_blank" rel="noopener noreferrer" aria-label="Open the recommended ${m.display} deck on MarvelCDB" title="MarvelCDB recommendation · ${deckRec.likes} likes · ${deckRec.selection==='recent'?'published within 12 months':'community classic'}">Deck pick ↗</a>`:'<span class="deck-pending" title="No published MarvelCDB deck yet">Deck pending</span>'):'';return `<div class="character ${m.role}" data-character="${id}" title="${m.display}${repeat?' — repeat appearance':''}">${repeat?'<span class="repeat" aria-label="Repeat appearance">🔁</span>':''}<div class="portrait"><span class="monogram">${initials(m.display)}</span><img loading="lazy" alt="${m.display} portrait" src="${url}" onload="this.parentElement.classList.add('loaded')" onerror="this.remove()"></div>${deck}<div class="character-name">${m.display}</div></div>`}
const MODULE_LABELS={official:['Official encounter setup','Official'],variable:['Variable official setup','Choose sets'],"self-contained":['Encounter modules','Self-contained'],campaign:['Official campaign setup','Pairing confirmed'],special:['Official special setup','Special setup']};
const TUNER_LABELS={official:'Official',easier:'Easier',thematic:'Thematic',harder:'Harder'};
function tunerFor(s){return DATA.difficultyTuner?.scenarios?.[s.id]||null}
function moduleSearchText(s){const info=DATA.encounterModules[s.id],tuner=tunerFor(s),tuned=tuner?['easier','thematic','harder'].flatMap(key=>{const choice=tuner[key];return choice?[choice.name,choice.notes,...choice.tags,...choice.mainSchemes,...choice.sets.map(set=>set.name)]:[]}):[];return info?[info.scenarioSet,...info.sets,info.note,...tuned].filter(Boolean).join(' '):''}
function formatDelta(value){return value===0?'±0':value>0?`+${value}`:String(value)}
function moduleRating(name){return DATA.difficultyTuner?.moduleRatings?.[ratingKey(name)]?.[state.playerCount]??null}
function ratingSummary(names){const ratings=names.map(moduleRating).filter(Number.isFinite),playerLabel=DATA.difficultyTuner.playerCounts[state.playerCount];if(!ratings.length)return`${playerLabel}: no matrix score for these required/story sets`;const minimum=Math.min(...ratings),maximum=Math.max(...ratings),average=ratings.reduce((sum,value)=>sum+value,0)/ratings.length,range=minimum===maximum?`level ${minimum}/10`:`levels ${minimum}–${maximum}/10 · avg ${average.toFixed(1)}`;return`${playerLabel}: ${range}${ratings.length<names.length?` · ${ratings.length}/${names.length} sets rated`:''}`}
function tunerButton(s,key,choice,active){const available=key==='official'||Boolean(choice),detail=key==='official'?'Printed setup':choice?formatDelta(choice.difficulty):'No published pick';return `<button class="tuner-choice ${key}${active?' active':''}" type="button" data-battle="${s.id}" data-choice="${key}" aria-pressed="${active}" ${available?'':`disabled title="No published VillainTheory ${key} alternative for this scenario"`}><span>${TUNER_LABELS[key]}</span><small>${detail}</small></button>`}
function selectedEncounter(s){const info=DATA.encounterModules[s.id],tuner=tunerFor(s),requested=state.moduleChoices[s.id]||'official',key=requested==='official'||tuner?.[requested]?requested:'official';if(key==='official')return{key,title:(MODULE_LABELS[info.type]||MODULE_LABELS.official)[0],difficulty:0,sets:info.sets.map(name=>({name})),mainSchemes:[],scenarioSet:info.scenarioSet||'',notes:info.note||'',url:'',source:'Fantasy Flight Games'};const choice=tuner[key];return{key,title:choice.name,difficulty:choice.difficulty,sets:choice.sets,mainSchemes:choice.mainSchemes,scenarioSet:'',notes:choice.notes,url:choice.url,source:'VillainTheory via Modular Champions',updated:choice.updated}}
function encounterModulesHtml(s){const info=DATA.encounterModules[s.id],tuner=tunerFor(s),selected=selectedEncounter(s),keys=['official','easier','thematic','harder'],buttons=keys.map(key=>tunerButton(s,key,key==='official'?null:tuner?.[key],selected.key===key)).join(''),chips=[];if(selected.scenarioSet)chips.push(`<span class="module-chip scenario">Scenario: ${escapeHtml(selected.scenarioSet)}</span>`);chips.push(...selected.mainSchemes.map(name=>`<span class="module-chip scheme">Main scheme: ${escapeHtml(name)}</span>`));if(selected.sets.length)chips.push(...selected.sets.map(set=>{const rating=moduleRating(set.name);return `<span class="module-chip">${escapeHtml(set.name)}${Number.isFinite(rating)?`<span class="module-level" title="${escapeHtml(DATA.difficultyTuner.playerCounts[state.playerCount])} difficulty level">${rating}/10</span>`:''}</span>`}));else if(info.type==='self-contained')chips.push('<span class="module-chip">No modular encounter set</span>');else if(info.type==='campaign')chips.push('<span class="module-chip">Additional printed modules not yet cataloged</span>');const names=selected.sets.map(set=>set.name),source=selected.url?`<a href="${selected.url}" target="_blank" rel="noreferrer">${selected.source} ↗</a>`:selected.source;return `<div class="module-block" data-battle="${s.id}"><div class="module-heading"><strong>Encounter tuner</strong><span class="module-status ${selected.key}">${TUNER_LABELS[selected.key]} ${formatDelta(selected.difficulty)}</span></div><div class="tuner-tabs" role="group" aria-label="Encounter setup for ${escapeHtml(s.title)}">${buttons}</div><div class="tuner-panel ${selected.key}"><div class="tuner-title"><strong>${escapeHtml(selected.title)}</strong><span>${formatDelta(selected.difficulty)} vs. printed setup</span></div><div class="module-list">${chips.join('')}</div>${selected.notes?`<p class="module-note">${escapeHtml(selected.notes)}</p>`:''}<div class="module-profile"><span>${escapeHtml(ratingSummary(names))}</span><span>${source}${selected.updated?` · updated ${escapeHtml(selected.updated)}`:''}</span></div></div><p class="tuner-attribution">Official stays the default. Alternatives are published VillainTheory recipes; deltas are relative to this villain. <a href="${DATA.difficultyTuner.source.recommendationsUrl}" target="_blank" rel="noreferrer">Source notes ↗</a></p></div>`}
function heroUsageRows(){const battlesByHero=new Map();for(const campaign of DATA.campaigns)for(const scenario of campaign.scenarios)for(const id of scenario.heroes){if(!battlesByHero.has(id))battlesByHero.set(id,[]);battlesByHero.get(id).push(scenario.number)}return [...battlesByHero].map(([id,battles])=>({id,name:DATA.characters[id].display,battles,appearances:battles.length,repeats:battles.length-1})).sort((a,b)=>b.appearances-a.appearances||a.name.localeCompare(b.name))}
function renderHeroUsage(){const rows=heroUsageRows(),appearanceMaximum=Math.max(...rows.map(row=>row.appearances)),repeatGaps=rows.flatMap(row=>row.battles.slice(1).map((battle,index)=>battle-row.battles[index])),closestRepeat=Math.min(...repeatGaps);$('#heroUsageSummary').textContent=`${rows.length} heroes · max ${appearanceMaximum}× · closest repeat ${closestRepeat} battles`;$('#heroUsage').innerHTML=rows.map(row=>`<div class="hero-usage-item" title="${row.name}: battles ${row.battles.map(battle=>String(battle).padStart(2,'0')).join(', ')}"><span class="hero-usage-name">${row.name}</span><span class="hero-usage-count">${row.appearances}× · ${row.repeats} repeat${row.repeats===1?'':'s'}</span></div>`).join('')}
function battleMatches(c,s){const q=norm(state.query);if(state.campaign!=='all'&&c.id!==state.campaign)return false;if(!q)return true;const chars=[...s.villains,...s.heroes].map(id=>DATA.characters[id]?.display||id).join(' ');return norm(`${c.campaign} ${s.title} ${s.context} ${chars} ${moduleSearchText(s)}`).includes(q)}
function render(){const root=$('#campaigns');let shown=0;root.innerHTML=DATA.campaigns.map((c,ci)=>{const sc=c.scenarios.filter(s=>battleMatches(c,s));if(!sc.length)return'';shown+=sc.length;return `<section class="campaign ${state.expanded?'':'collapsed'}" id="${c.id}"><button class="campaign-head" onclick="toggleCampaign(this)" aria-expanded="${state.expanded}"><span class="campaign-index">${String(ci+1).padStart(2,'0')}</span><span><h2>${c.campaign}</h2><div class="campaign-meta">${sc.length} matchup${sc.length===1?'':'s'}</div></span><span class="chevron">⌄</span></button>${c.note?`<p class="campaign-note">${c.note}</p>`:''}<div class="campaign-body">${sc.map(s=>battleHtml(s)).join('')}</div></section>`}).join('');if(!shown)root.innerHTML='<div class="empty">No battles match those filters. <button class="btn" onclick="resetFilters()">Show all matchups</button></div>';$('#shownCount').textContent=shown;updateFilterFeedback(shown)}
function battleHtml(s){const heroAssignments=s.heroAssignments.filter(a=>!(state.hideRepeats&&a.repeat));return `<article class="battle" id="${s.id}"><div><div class="battle-number">Battle ${String(s.number).padStart(2,'0')}</div><h3>${s.title}</h3><div class="side-label">Villain side</div><div class="roster">${s.villains.map(id=>characterCard(id,false)).join('')}</div></div><div><div class="side-label">Thematic hero team</div><div class="roster">${heroAssignments.length?heroAssignments.map(a=>characterCard(a.id,a.repeat)).join(''):'<span class="campaign-meta">Repeat heroes hidden</span>'}</div></div><div class="battle-context"><strong>Why this battle works</strong><span>${s.context}</span>${encounterModulesHtml(s)}</div></article>`}
function scenarioById(id){for(const campaign of DATA.campaigns){const scenario=campaign.scenarios.find(item=>item.id===id);if(scenario)return scenario}return null}
function refreshEncounterBlock(battleId){const scenario=scenarioById(battleId),block=document.querySelector(`#${battleId} .module-block`);if(scenario&&block)block.outerHTML=encounterModulesHtml(scenario)}
function chooseEncounter(battleId,key){const scenario=scenarioById(battleId),tuner=scenario?tunerFor(scenario):null;if(!scenario||!TUNER_LABELS[key]||(key!=='official'&&!tuner?.[key]))return;if(key==='official')delete state.moduleChoices[battleId];else state.moduleChoices[battleId]=key;persistTunerSettings();refreshEncounterBlock(battleId)}
function setPlayerCount(playerCount){if(!DATA.difficultyTuner.playerCounts[playerCount])return;state.playerCount=playerCount;persistTunerSettings();$$('.module-block[data-battle]').forEach(block=>refreshEncounterBlock(block.dataset.battle))}
function toggleCampaign(btn){const collapsed=btn.closest('.campaign').classList.toggle('collapsed');btn.setAttribute('aria-expanded',String(!collapsed))}
function initControls(){const sel=$('#campaignSelect'),playerSelect=$('#playerCount'),mobileToolsToggle=$('#mobileToolsToggle');sel.innerHTML='<option value="all">All campaigns</option>'+DATA.campaigns.map(c=>`<option value="${c.id}">${c.campaign}</option>`).join('');playerSelect.innerHTML=Object.entries(DATA.difficultyTuner.playerCounts).map(([value,label])=>`<option value="${value}">${label} tuner</option>`).join('');playerSelect.value=state.playerCount;$('#search').addEventListener('input',e=>{state.query=e.target.value;render()});sel.addEventListener('change',e=>{state.campaign=e.target.value;syncChips();render()});playerSelect.addEventListener('change',e=>setPlayerCount(e.target.value));mobileToolsToggle.addEventListener('click',e=>{const open=$('.toolbar').classList.toggle('mobile-tools-open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'Close':'Tools'});$('#campaigns').addEventListener('click',e=>{const button=e.target.closest('.tuner-choice');if(button)chooseEncounter(button.dataset.battle,button.dataset.choice)});$('#hideRepeats').addEventListener('click',e=>{state.hideRepeats=!state.hideRepeats;e.currentTarget.classList.toggle('primary',state.hideRepeats);e.currentTarget.textContent=state.hideRepeats?'Show repeat heroes':'Hide repeat heroes';render()});$('#expand').addEventListener('click',e=>{state.expanded=!state.expanded;e.currentTarget.textContent=state.expanded?'Collapse all':'Expand all';render()});const strip=$('#campaignChips');strip.innerHTML=`<button class="filter-chip active" data-id="all">All</button>`+DATA.campaigns.map(c=>`<button class="filter-chip" data-id="${c.id}">${c.campaign}</button>`).join('');strip.addEventListener('click',e=>{const b=e.target.closest('.filter-chip');if(!b)return;state.campaign=b.dataset.id;sel.value=state.campaign;syncChips();render()})}
function syncChips(){$$('.filter-chip').forEach(b=>b.classList.toggle('active',b.dataset.id===state.campaign))}
function updateFilterFeedback(shown){const active=Boolean(state.query||state.campaign!=='all'||state.hideRepeats);const details=[];if(state.query)details.push(`search “${state.query}”`);if(state.campaign!=='all')details.push($('#campaignSelect').selectedOptions[0].textContent);if(state.hideRepeats)details.push('repeat heroes hidden');$('#filterFeedback').innerHTML=`Showing <strong>${shown}</strong> of 65 matchups${details.length?' · '+details.join(' · '):''}`;$('#resetFilters').disabled=!active}
function resetFilters(){state.query='';state.campaign='all';state.hideRepeats=false;$('#search').value='';$('#campaignSelect').value='all';$('#hideRepeats').classList.remove('primary');$('#hideRepeats').textContent='Hide repeat heroes';syncChips();render();$('#search').focus()}
function selectedEncounterText(s){const selected=selectedEncounter(s),parts=[selected.scenarioSet?`Scenario: ${selected.scenarioSet}`:'',...selected.mainSchemes.map(name=>`Main scheme: ${name}`),...selected.sets.map(set=>set.name)].filter(Boolean),setup=parts.join(' + ')||'No modular encounter set',profile=ratingSummary(selected.sets.map(set=>set.name));return`${TUNER_LABELS[selected.key]} ${formatDelta(selected.difficulty)} — ${selected.title}: ${setup}${selected.notes?` — ${selected.notes}`:''}\nPlayer-count profile: ${profile}${selected.url?`\nVillainTheory recipe: ${selected.url}`:''}`}
function workChatText(){let out=`MARVEL CHAMPIONS THEMATIC TWO-HERO MATCHUPS\nCanonical sequence: ${DATA.rules.scope}\nRepeat marker: ${DATA.rules.repeatMarker} means the hero appeared earlier.\nConstraint: ${DATA.rules.sequenceNote}\nEncounter tuner: ${DATA.difficultyTuner.playerCounts[state.playerCount]}; official setup remains the default.\n\n`;for(const c of DATA.campaigns){out+=`## ${c.campaign}\n`;if(c.note)out+=`Note: ${c.note}\n`;for(const s of c.scenarios){const vs=s.villains.map(x=>DATA.characters[x].display).join(' + '),hs=s.heroAssignments.map(a=>DATA.characters[a.id].display+(a.repeat?' 🔁':'')).join(' + ');out+=`${s.number}. ${s.title}\nVillain(s): ${vs}\nHeroes: ${hs}\nEncounter setup: ${selectedEncounterText(s)}\nContext: ${s.context}\n\n`}}out+='Use this sequence as the source of truth. Preserve order, pairings, release gating, repeat markers, and the selected encounter setup unless explicitly asked to revise them.';return out}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
async function copyBrief(){try{await navigator.clipboard.writeText(workChatText());toast('Work-chat brief copied')}catch{const ta=document.createElement('textarea');ta.value=workChatText();document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('Work-chat brief copied')}}
function downloadJson(){const blob=new Blob([JSON.stringify(DATA,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='marvel-champions-matchups.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
document.addEventListener('DOMContentLoaded',()=>{initControls();renderHeroUsage();render();$('#artStatus').classList.add('hidden');$('#resetFilters').addEventListener('click',resetFilters);$('#copyBrief').addEventListener('click',copyBrief);$('#downloadJson').addEventListener('click',downloadJson);$('#print').addEventListener('click',()=>window.print());document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(state.query||state.campaign!=='all'||state.hideRepeats))resetFilters()})});
